
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_gga_x_pw91_mod_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("gga_x_pw91_mod", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-4.322468762109199e+00, -4.240715344257452e+00, -4.126246347340899e+00, -3.967859974462456e+00, -3.752415847646829e+00, -3.466455466766326e+00, -3.099975352691096e+00, -2.653085433585885e+00, -2.144348549879820e+00, -1.612229862526484e+00, -1.090225687615594e+00, -7.115754790683373e-01, -6.041765053335879e-01, -5.038383902163737e-01, -3.717143286784895e-01, -2.433609061027558e-01, -1.323047191494800e-01, -2.350303311213165e-02, -2.483981672983860e-04, -3.316405883581921e-07]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


